  // ============ CALCULATOR - AUTO-CALCULATE ============
  const calcPress = (key) => {
    // Toggle scientific functions
    if (key === 'sciToggle') {
      setShowScientific(!showScientific);
      return;
    }

    // AC - Clear everything
    if (key === 'AC') {
      setCalcDisplay('0');
      setCalcPrev(null);
      setCalcOp(null);
      setCalcWaiting(false);
      setCalcSecret('');
      setCalcExpression('');
      return;
    }

    // DEL - Delete last character
    if (key === 'DEL') {
      if (calcDisplay.length > 1) {
        setCalcDisplay(calcDisplay.slice(0, -1));
        setCalcSecret(calcSecret.slice(0, -1));
      } else {
        setCalcDisplay('0');
        setCalcSecret('');
      }
      return;
    }

    // Scientific functions
    const sciKeys = ['sin', 'cos', 'tan', 'log', '√', 'π', 'e'];
    if (sciKeys.includes(key)) {
      const num = parseFloat(calcDisplay);
      let result;
      switch (key) {
        case 'sin': result = Math.sin((num * Math.PI) / 180); break;
        case 'cos': result = Math.cos((num * Math.PI) / 180); break;
        case 'tan': result = Math.tan((num * Math.PI) / 180); break;
        case 'log': result = Math.log10(num); break;
        case '√': result = Math.sqrt(num); break;
        case 'π': result = Math.PI; break;
        case 'e': result = Math.E; break;
        default: result = num;
      }
      setCalcDisplay(isNaN(result) ? 'Error' : String(result));
      setCalcExpression(key + '(' + num + ')');
      setCalcWaiting(true);
      return;
    }

    // ========== EQUALS ==========
    if (key === '=') {
      // Check unlock
      if (calcSecret === pin) {
        setUnlocked(true);
        setCalcDisplay('0');
        setCalcSecret('');
        setCalcPrev(null);
        setCalcOp(null);
        setCalcWaiting(false);
        setCalcExpression('');
        loadData();
        toast('🔓 Welcome to AURA');
        return;
      }
      
      // If there's a pending operation, calculate it
      if (calcOp && !calcWaiting) {
        const num = parseFloat(calcDisplay);
        let result;
        switch (calcOp) {
          case '+': result = calcPrev + num; break;
          case '-': result = calcPrev - num; break;
          case '×': result = calcPrev * num; break;
          case '÷': result = num === 0 ? NaN : calcPrev / num; break;
          default: result = num;
        }
        const displayResult = isNaN(result) ? 'Error' : String(result);
        
        // Get the full expression before calculation
        const fullExpression = calcExpression || (calcPrev + ' ' + calcOp + ' ' + num);
        
        setCalcDisplay(displayResult);
        setCalcExpression(fullExpression + ' = ' + displayResult);
        setCalcPrev(null);
        setCalcOp(null);
        setCalcWaiting(false);
        setCalcSecret('');
        return;
      }
      
      // If no operation, just return
      setCalcSecret('');
      return;
    }

    // Numbers
    if (/^[0-9]$/.test(key)) {
      setCalcSecret(calcSecret + key);
      
      // If we're waiting for a new number (after operator)
      if (calcWaiting) {
        setCalcDisplay(key);
        setCalcWaiting(false);
        setCalcExpression((calcExpression || '') + key);
        return;
      }
      
      // Normal number input
      const newDisplay = calcDisplay === '0' ? key : calcDisplay + key;
      setCalcDisplay(newDisplay);
      setCalcExpression(prev => prev + key);
      
      // Auto-calculate while typing (only if there's a pending operation)
      if (calcOp && !calcWaiting) {
        const num = parseFloat(newDisplay);
        let result;
        switch (calcOp) {
          case '+': result = calcPrev + num; break;
          case '-': result = calcPrev - num; break;
          case '×': result = calcPrev * num; break;
          case '÷': result = num === 0 ? NaN : calcPrev / num; break;
          default: result = num;
        }
        const displayResult = isNaN(result) ? 'Error' : String(result);
        setCalcDisplay(displayResult);
        setCalcSecret(calcSecret + key);
        setCalcWaiting(false);
      }
      return;
    }

    // Decimal
    if (key === '.') {
      if (calcWaiting) {
        setCalcDisplay('0.');
        setCalcWaiting(false);
        setCalcExpression((calcExpression || '') + '0.');
        return;
      }
      if (!calcDisplay.includes('.')) {
        setCalcDisplay(calcDisplay + '.');
        setCalcExpression(prev => prev + '.');
      }
      return;
    }

    // Operators
    if (['+', '-', '×', '÷'].includes(key)) {
      const num = parseFloat(calcDisplay);
      const expr = calcExpression || calcDisplay;
      
      // If there's already a pending operation, calculate it first
      if (calcOp && !calcWaiting) {
        let result;
        switch (calcOp) {
          case '+': result = calcPrev + num; break;
          case '-': result = calcPrev - num; break;
          case '×': result = calcPrev * num; break;
          case '÷': result = num === 0 ? NaN : calcPrev / num; break;
          default: result = num;
        }
        const displayResult = isNaN(result) ? 'Error' : String(result);
        setCalcDisplay(displayResult);
        setCalcPrev(result);
        setCalcExpression(displayResult + key);
        setCalcOp(key);
        setCalcWaiting(true);
      } else {
        setCalcExpression(expr + key);
        setCalcPrev(parseFloat(calcDisplay));
        setCalcOp(key);
        setCalcWaiting(true);
      }
      return;
    }

    // +/- toggle
    if (key === '±') {
      if (calcDisplay !== '0' && calcDisplay !== 'Error') {
        const newDisplay = calcDisplay.startsWith('-') ? calcDisplay.slice(1) : '-' + calcDisplay;
        setCalcDisplay(newDisplay);
        const expr = calcExpression || calcDisplay;
        if (expr.startsWith('-')) {
          setCalcExpression(expr.slice(1));
        } else {
          setCalcExpression('-' + expr);
        }
      }
      return;
    }

    // Percentage
    if (key === '%') {
      const num = parseFloat(calcDisplay);
      const result = num / 100;
      setCalcDisplay(String(result));
      setCalcExpression(String(result));
      return;
    }
  };

  // ============ POSTS ============
  const fetchPosts = useCallback(async (cat) => {
