  // ============ SOS ============
const triggerSOS = () => {
  if (!navigator.geolocation) {
    setSosStatus("❌ This browser doesn't support GPS.");
    return;
  }

  if (isSOSActive) {
    if (sosInterval) {
      clearInterval(sosInterval);
