      setSosStatus(`📍 LIVE: ${address || `${lat.toFixed(5)}, ${lng.toFixed(5)}`}`);
      
      // SEND SOS - WORKS OFFLINE
      await sendLiveSOS(locationData);
      
      setIsSOSActive(true);
      
      if (sosInterval) clearInterval(sosInterval);
      
      const interval = setInterval(() => {
        navigator.geolocation.getCurrentPosition(
          async (pos2) => {
            const { latitude: lat2, longitude: lng2 } = pos2.coords;
            
            let address2 = null;
            try {
              const res = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat2}&lon=${lng2}&zoom=16`);
              const data = await res.json();
              address2 = data.display_name || null;
            } catch (e) {}
            
            const newLocation = { lat: lat2, lng: lng2, address: address2 };
            setSosLocation(newLocation);
            setSosStatus(`📍 LIVE: ${address2 || `${lat2.toFixed(5)}, ${lng2.toFixed(5)}`}`);
            
            if (mapRef.current) {
              mapRef.current.setView([lat2, lng2], 16);
            }
            
            await sendLiveSOS(newLocation);
          },
          (err) => {
            console.log('Live update failed:', err.message);
          },
          { enableHighAccuracy: true, timeout: 10000 }
        );
      }, 8000);
      
      setSosInterval(interval);
