              borderBottom: '1px solid var(--card-bd)',
              textAlign: 'center'
            }}>
              {syncStatus}
            </div>
          )}

          {/* ========== NOTIFICATIONS PANEL ========== */}
          {/* ========== NOTIFICATIONS PANEL ========== */}
{showNotifications && (
